tasks.check:
set -o pipefail
cd /home/bcorfman/dev/freytag-forge
export PYTHONPATH=$PWD TMPDIR=/tmp
PY=.venv/bin/python
CH=$(git status --porcelain | awk '{print $NF}' | sort | tr '\n' ' ')
for f in scripts/ringer/phase1/act2_probe.py tests/test_act2_probe.py; do echo "$CH" | grep -q "$f" || { echo "WHY: $f not modified"; exit 1; }; done
grep -q "Trace the cable run along the gate wall." scripts/ringer/phase1/act2_probe.py || { echo "WHY: pure_missed_window command not replaced"; exit 1; }
grep -q "Give my supervisor a long, vague explanation of the failing water pressure." scripts/ringer/phase1/act2_probe.py || { echo "WHY: doubted command not replaced"; exit 1; }
grep -q "Ask Rebecca what she offers for Michelle." scripts/ringer/phase1/act2_probe.py || { echo "WHY: rescue prefix not replaced"; exit 1; }
grep -q "Explain my vague cooling-water" scripts/ringer/phase1/act2_probe.py && { echo "WHY: old doubted command remains"; exit 1; }
$PY -m ruff format --check scripts/ringer/phase1/act2_probe.py tests/test_act2_probe.py || { echo "WHY: not ruff-formatted"; exit 1; }
$PY -m ruff check scripts/ringer/phase1/act2_probe.py tests/test_act2_probe.py || { echo "WHY: ruff check failed"; exit 1; }
grep -q "_matches_all" tests/test_act2_probe.py || { echo "WHY: tests do not use the real matcher"; exit 1; }
for row in "2A pure_missed_window" "2A doubted" "2B erased" "2C rescue"; do set -- $row; O=$(mktemp -d); $PY scripts/ringer/phase1/act2_probe.py --scene $1 --prefix $2 --n 1 --out $O --dry-run || { echo "WHY: dry run failed for $row"; exit 1; }; $PY scripts/ringer/phase1/check_act2_probe.py $O 1 --mode dry || { echo "WHY: artifact check failed for $row"; exit 1; }; done
$PY -m pytest -q -p no:cacheprovider tests/test_act2_probe.py tests/test_act3a_probe.py || { echo "WHY: probe tests failed"; exit 1; }
echo ok
